create extension if not exists pgcrypto;
create table if not exists public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,email text,reputation int not null default 0,prestige_marks int not null default 0,created_at timestamptz default now());
create table if not exists public.currencies(user_id uuid primary key references auth.users(id) on delete cascade,credit bigint not null default 1000,shard numeric(20,4) not null default 0,updated_at timestamptz default now());
create table if not exists public.modules(user_id uuid references auth.users(id) on delete cascade,type text check(type in('energy','workshop','storage','lab')),level int not null default 1,upgrade_started_at timestamptz,upgrade_ends_at timestamptz,primary key(user_id,type));
create table if not exists public.energy(user_id uuid primary key references auth.users(id) on delete cascade,current int not null default 100,updated_at timestamptz default now());
create table if not exists public.explorers(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,stats jsonb not null,rarity text not null default 'Common',level int not null default 1,gear jsonb not null default '{}',status text not null default 'idle');
create table if not exists public.items(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,type text not null,subtype text,amount int default 1,durability int,rarity text default 'Common',metadata jsonb default '{}');
create table if not exists public.recipes(id int primary key,name text not null,materials jsonb not null,credit_cost int not null,time_minutes int not null);
create table if not exists public.craft_queue(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,recipe_id int references recipes(id),started_at timestamptz default now(),completes_at timestamptz,status text default 'active');
create table if not exists public.zones(id int primary key,name text not null,hazard numeric not null,energy_cost int not null,duration int not null,credit_yield int not null,shard_yield numeric not null,config jsonb default '{}');
create table if not exists public.missions(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,zone_id int references zones(id),explorer_id uuid references explorers(id),status text default 'active',started_at timestamptz default now(),resolved_at timestamptz,outcome text,hazard_effective numeric,yield_multiplier numeric default 1);
create table if not exists public.mission_events(mission_id uuid references missions(id) on delete cascade,event_index int,choice int,result text,clue text,choices jsonb,primary key(mission_id,event_index));
create table if not exists public.inventory_ledger(id bigserial primary key,user_id uuid references auth.users(id),item_type text,amount_change int,reason text,created_at timestamptz default now());
create table if not exists public.market_listings(id uuid primary key default gen_random_uuid(),item_id uuid references items(id),price bigint check(price>0),seller_id uuid references auth.users(id),status text default 'active',created_at timestamptz default now());
create table if not exists public.market_trades(id uuid primary key default gen_random_uuid(),listing_id uuid,item_id uuid,buyer_id uuid,seller_id uuid,price bigint,tax_burn numeric,tax_treasury numeric,tax_rewards numeric,flagged boolean default false,created_at timestamptz default now());
create table if not exists public.ledger(id bigserial primary key,user_id uuid references auth.users(id),shard_delta numeric(20,4),reason text,signature text,created_at timestamptz default now());
create table if not exists public.guilds(id uuid primary key default gen_random_uuid(),name text unique,created_by uuid references auth.users(id),hall_level int default 1);
create table if not exists public.guild_members(guild_id uuid references guilds(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role text default 'member',joined_at timestamptz default now(),primary key(guild_id,user_id));
create table if not exists public.raids(id uuid primary key default gen_random_uuid(),zone_id int references zones(id),started_at timestamptz default now(),ended_at timestamptz,participants jsonb default '[]');
create table if not exists public.seasons(id int primary key,name text,start_date date,end_date date,config jsonb default '{}');
create table if not exists public.season_pass(user_id uuid references auth.users(id) on delete cascade,season_id int references seasons(id),tier int default 0,premium boolean default false,primary key(user_id,season_id));
create table if not exists public.leaderboard_snapshots(season_id int references seasons(id),user_id uuid references auth.users(id),rank int,score int,rewards jsonb default '{}',primary key(season_id,user_id));
create table if not exists public.achievements(id int primary key,name text,description text,reward jsonb default '{}');create table if not exists public.user_achievements(user_id uuid references auth.users(id) on delete cascade,achievement_id int references achievements(id),earned_at timestamptz default now(),primary key(user_id,achievement_id));
create table if not exists public.balance_config(key text primary key,value jsonb not null,updated_at timestamptz default now());
create table if not exists public.audit_logs(id bigserial primary key,user_id uuid references auth.users(id),action text,details jsonb default '{}',created_at timestamptz default now());
create table if not exists public.risk_scores(user_id uuid primary key references auth.users(id) on delete cascade,score numeric default 0,updated_at timestamptz default now());
create index if not exists missions_user_status on missions(user_id,status);create index if not exists market_active on market_listings(status,created_at);create index if not exists ledger_user on ledger(user_id,created_at);
create or replace function public.bootstrap_voidrun_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into profiles(user_id,email) values(new.id,new.email) on conflict do nothing;insert into currencies(user_id) values(new.id) on conflict do nothing;insert into energy(user_id) values(new.id) on conflict do nothing;insert into risk_scores(user_id) values(new.id) on conflict do nothing;insert into modules(user_id,type) select new.id,x from unnest(array['energy','workshop','storage','lab']) x on conflict do nothing;insert into explorers(user_id,stats) values(new.id,'{"Speed":5,"Luck":5,"Strength":5,"Focus":5}') ;return new;end$$;
drop trigger if exists voidrun_user_init on auth.users;create trigger voidrun_user_init after insert on auth.users for each row execute function public.bootstrap_voidrun_user();
alter table profiles enable row level security;alter table currencies enable row level security;alter table modules enable row level security;alter table energy enable row level security;alter table explorers enable row level security;alter table items enable row level security;alter table missions enable row level security;alter table market_listings enable row level security;alter table ledger enable row level security;alter table guilds enable row level security;alter table guild_members enable row level security;alter table user_achievements enable row level security;alter table risk_scores enable row level security;
create policy profiles_self on profiles for select using(auth.uid()=user_id);create policy currencies_self on currencies for select using(auth.uid()=user_id);create policy modules_self on modules for select using(auth.uid()=user_id);create policy energy_self on energy for select using(auth.uid()=user_id);create policy explorers_self on explorers for select using(auth.uid()=user_id);create policy items_self on items for select using(auth.uid()=user_id);create policy missions_self on missions for select using(auth.uid()=user_id);create policy market_public on market_listings for select using(status='active');create policy guild_public on guilds for select using(true);create policy guild_members_public on guild_members for select using(true);create policy seasons_public on seasons for select using(true);create policy leaderboard_public on leaderboard_snapshots for select using(true);create policy user_achievements_self on user_achievements for select using(auth.uid()=user_id);
insert into zones(id,name,hazard,energy_cost,duration,credit_yield,shard_yield) values(1,'Dark Edge',.10,10,180,10,.2),(2,'Crystal Grove',.25,18,360,22,.6),(3,'Silica Desert',.40,28,720,45,1.5),(4,'Ion Rift',.60,40,1500,90,3.5),(5,'Void Core',.80,55,2700,170,8),(6,'Group Assault',.90,80,3600,400,20) on conflict(id) do update set name=excluded.name,hazard=excluded.hazard,energy_cost=excluded.energy_cost,duration=excluded.duration,credit_yield=excluded.credit_yield,shard_yield=excluded.shard_yield;
insert into balance_config(key,value) values('economy','{"target_ratio_min":0.9,"target_ratio_max":1.1,"emission_k":1,"emission_max":100000}'::jsonb),('market_tax','{"burn":0.02,"treasury":0.02,"rewards":0.01}'::jsonb),('modules','{"energy":{"c0":100,"t0":2},"workshop":{"c0":120,"t0":2},"storage":{"c0":110,"t0":2},"lab":{"c0":140,"t0":2}}'::jsonb) on conflict(key) do nothing;
insert into recipes(id,name,materials,credit_cost,time_minutes) values(1,'Reinforced Suit','{"Metal":3,"Polymer":1}',120,240) on conflict(id) do nothing;insert into seasons values(1,'Season 1 — Awakening',current_date,current_date+56,'{}') on conflict(id) do nothing;
